public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();

    String s = sc.next();
    String t = sc.next();

    Deque<Integer> queA = new ArrayDeque<Integer>();
    Deque<Integer> queB = new ArrayDeque<Integer>();
    int result = 0;

    for(int i = 0; i < n; i++) {
        if(s.charAt(i) == 'B' && t.charAt(i) == 'A') {
            queA.add(i);
        }
        if(s.charAt(i) == 'A' && t.charAt(i) == 'B') {
            queB.add(i);
        }
    }

    while(!queA.isEmpty() && !queB.isEmpty()) {
        int indexA = queA.peek();
        int indexB = queB.peek();

        if(indexA < indexB) {
            result++;
            queA.poll();
            queB.poll();
        } else {
            System.out.println(-1);
            return;
        }
    }

    if(!queA.isEmpty() || !queB.isEmpty()) {
        System.out.println(-1);
    } else {
        System.out.println(result);
    }
}
